/** The items of a list value, trimmed, first occurrence kept. */
function items(declared, text) {
  if (text === '') return []

  const split = text.split(',')
  const result = []
  const seen = new Set()

  for (const item of split) {
    const trimmed = item.trim()
    if (trimmed === '') throw new ValueError(`${declared.key} has an empty item: ${text}`)
    if (!seen.has(trimmed)) {
      result.push(trimmed)
      seen.add(trimmed)
    }
  }

  return result
}

